/* ---------- Filter menu ---------- */
/* a list's filter bar: a Filter button that opens a two-step menu (a field, then its value), the filters as chips, and
   the issues that match under them. Its content sits 16px in from every edge in every style; each issue's row has its hover
   fill reaching out 8px round its dot and words, with the card's rounding. The menu opens over the list, under the button,
   and never moves the card; the list grows and shrinks with what matches (grow()), keeping no room for rows to come */
.dm-flm{width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-flm-bar{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.dm-flm-chips{display:contents}
.dm-flm-tr{padding:0 11px 0 9px}
.dm-flm-tr .dm-i{color:var(--dm-fg2)}
.dm-flm-tr[aria-expanded="true"]{background:var(--dm-chip)}
.dm-flm :is(.dm-pill,.dm-ib):active{transform:none}
.dm-flm-ch{display:inline-flex;align-items:center;height:28px;padding-left:9px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);font-size:12.5px;white-space:nowrap;max-width:100%;animation:dm-popin .4s var(--dm-ease) backwards}
.dm-flm-ch.dm-seen{animation:none}
.dm-flm-ch .dm-k{color:var(--dm-fg2)}
.dm-flm-ch .dm-op{height:22px;padding:0 5px;margin:0 1px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));color:var(--dm-muted);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-flm-ch .dm-op:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-flm-ch .dm-v{font-weight:500;overflow:hidden;text-overflow:ellipsis}
.dm-flm-ch .dm-x{width:26px;height:28px;display:grid;place-items:center;flex:none;color:var(--dm-muted);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-flm-ch .dm-x:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-flm-ch.dm-gone{animation:dm-leave .3s var(--dm-ease) both}
.dm-flm-pop{width:232px}
.dm-flm-lv[hidden]{display:none}
.dm-flm-pop .dm-mi .dm-r{margin-left:auto}
.dm-flm-pop .dm-mi .dm-ck{margin-left:0}
.dm-flm-pop .dm-mi .dm-r+.dm-ck,.dm-flm-pop .dm-mi .dm-r+.dm-i{margin-left:0}
