.dm-flm-pop .dm-mi .dm-av{width:20px;height:20px;font-size:9px}
.dm-flm-pop .dm-mi .dm-dot{width:8px;height:8px;margin:0 3px}
.dm-flm-bk{color:var(--dm-fg2)}
/* the count and Clear all: the count on the content's left edge, Clear all's words ending on its right edge with its hover box
   reaching out round them */
.dm-flm-sum{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:28px;margin:0 calc(-1 * var(--dm-s-4));padding:var(--dm-s-3) var(--dm-s-4) 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px;color:var(--dm-fg2)}
.dm-flm-clr{margin-right:-11px}
/* text buttons here (Clear all, and Ticket list's Edit and Context menu's Undo) hover with a quiet fill that shows on a white card */
@media (hover:hover) and (pointer:fine){:is(.dm-flm,.dm-tkx,.dm-cxm) .dm-pill.dm-ghost:hover{background:var(--dm-row)}}
.dm-flm-list{display:flex;flex-direction:column;margin:-4px -8px -8px}
.dm-flm-r{display:grid;grid-template-columns:auto minmax(0,1fr) auto 44px;align-items:center;gap:10px;padding:var(--dm-s-2);border-radius:calc(var(--dm-r-card) - 8px);font-size:13px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-flm-r:hover{background:color-mix(in srgb,var(--dm-fg) 4%,transparent)}}
.dm-flm-r .dm-dot{width:8px;height:8px}
.dm-flm-r .dm-t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-flm-r .dm-av{width:20px;height:20px;font-size:9px}
.dm-flm-r .dm-a{font-size:12px;color:var(--dm-muted);text-align:right}
