.dm-flm-em-art::after{content:"";position:absolute;left:32px;top:17px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 55%,var(--dm-surface)))}
:root:not([data-style="soft"],[data-style="clean"]) .dm-flm-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px var(--dm-line)}
.dm-flm .dm-dot[data-s="open"]{color:var(--dm-flm-open)}.dm-flm .dm-dot[data-s="prog"]{color:var(--dm-flm-prog)}.dm-flm .dm-dot[data-s="done"]{color:var(--dm-flm-done)}
/* the status dots are the vivid marks, 3:1 on the surface in every style and theme: open is the accent's mark, in progress the
   warning's and done the green's. Blueprint's accent mark is the same green as done, so its open dot takes the chart palette's
   blue (--dm-c3) instead */
